export const DEFAULT_LOCALITY_ID = 'sholinganallur'

export const getLocality = (id) =>
  LOCALITIES.find((l) => l.id === id) || LOCALITIES.find((l) => l.id === DEFAULT_LOCALITY_ID)

// City-overview camera target — high enough to frame all localities at once.
export const CHENNAI_CITY = {
  lon: LOCALITIES.reduce((s, l) => s + l.base.lon, 0) / LOCALITIES.length,
  lat: LOCALITIES.reduce((s, l) => s + l.base.lat, 0) / LOCALITIES.length,
  cameraHeightM: 26000,
}

// Trimmed registry safe to ship to the browser (no generator config).
export const localityPublic = (l) => ({
  id: l.id,
  name: l.name,
  label: l.label,
  base: l.base,
  ulpinPrimary: l.ulpinPrimary,
  zone: l.zone,
  adminLevel: l.adminLevel || null,
  recordType: l.recordType || null,
  cameraHeightM: l.cameraHeightM,
  extentM: l.extentM,
})
